'use strict';
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',video:'<rect x="3" y="5" width="12" height="14" rx="2"/><path d="m15 10 6-4v12l-6-4Z"/>',file:'<path d="M14 2H5v20h14V7Z M14 2v6h5M8 12h8m-8 4h6"/>',ambulance:'<path d="M3 6h11v12H3ZM14 10h4l3 4v4h-7M7 9v5m-2-2h4"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 7 0 0 1 16 0v2"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/><path d="M3 12h5l2-4 4 8 2-4h5"/>',shield:'<path d="m12 2 8 4v7c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',check:'<path d="m5 12 4 4L19 6"/>',cross:'<path d="M8 3h8v5h5v8h-5v5H8v-5H3V8h5Z"/>',pill:'<path d="m9 15 6-6m-9 9a5 5 0 0 1 0-7l5-5a5 5 0 0 1 7 7l-5 5a5 5 0 0 1-7 0Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',phone:'<path d="M5 3h4l2 5-3 2a15 15 0 0 0 6 6l2-3 5 2v4c0 2-3 3-6 2C9 19 5 15 3 9 2 6 3 3 5 3Z"/>',refresh:'<path d="M20 10a8 8 0 1 0-1 7M20 3v7h-7"/>',hospital:'<path d="M4 21V6h16v15M9 21v-6h6v6M10 3h4m-2 5v4m-2-2h4M1 21h22"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.cross}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['home','Início','home'],['discover','Encontrar cuidados','search'],['appointments','Consultas','calendar'],['video','Teleconsulta','video'],['documents','Documentos','file'],['ambulance','Ambulância','ambulance'],['profile','Meu perfil','user']];
const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const dayIso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const initialBooking={id:1,specialty:'Medicina geral',doctor:'Dra. Ana · perfil de exemplo',type:'Teleconsulta',date:dayIso(tomorrow),time:'10:30'};
const state={category:'Todos',query:'',area:'Luanda',bookings:[{...initialBooking}],slot:'10:30',docs:false,videoActive:false,mic:true,camera:true,ambulance:false};
const providers=[{name:'Farmácia KAYA Central',type:'Farmácias',zone:'Maianga',hours:'08:00–20:00',icon:'pill'},{name:'Clínica KAYA Família',type:'Clínicas',zone:'Talatona',hours:'08:00–18:00',icon:'hospital'},{name:'Farmácia KAYA Sul',type:'Farmácias',zone:'Talatona',hours:'08:00–22:00',icon:'pill'},{name:'Centro de Diagnóstico KAYA',type:'Laboratórios',zone:'Maianga',hours:'07:00–16:00',icon:'cross'}];
const areas={Luanda:[13.20,-8.91,13.30,-8.77],Maianga:[13.22,-8.85,13.26,-8.80],Talatona:[13.17,-8.96,13.22,-8.89]};
const apiBase='https://ca-kaya-care-api.politecliff-e1e56015.spaincentral.azurecontainerapps.io';
let toastTimer;
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200)}
function go(page){if(location.hash===`#${page}`)render();else location.hash=page}
function current(){const p=location.hash.slice(1);return nav.some(n=>n[0]===p)?p:'home'}
function button(text,action,kind='',extra=''){return `<button class="btn ${kind}" data-action="${action}" ${extra}>${text}</button>`}
function pageButton(text,page,kind=''){return `<button class="btn ${kind}" data-page="${page}" aria-label="${esc(text.replace(/<[^>]*>/g,'').trim() || nav.find(n=>n[0]===page)?.[1] || page)}">${text}</button>`}
function note(s='Demonstração com dados fictícios. Nenhuma consulta, chamada ou pedido real será enviado.'){return `<div class="demo-note">${icon('info')}<span>${s}</span></div>`}
function intro(kicker,title,description){return `<div class="page-intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><span class="date">${new Date().toLocaleDateString('pt-PT',{day:'numeric',month:'long',year:'numeric'})}</span></div>`}
function dateLabel(iso){return new Date(iso+'T12:00:00').toLocaleDateString('pt-PT',{day:'numeric',month:'short'})}
function map(area='Luanda'){return `<div class="map-card"><iframe title="Mapa de ${esc(area)} — OpenStreetMap" loading="lazy" referrerpolicy="no-referrer" src="https://www.openstreetmap.org/export/embed.html?bbox=${areas[area].join('%2C')}&amp;layer=mapnik"></iframe><div class="map-caption">${icon('pin')} Mapa real de ${esc(area)} · © OpenStreetMap contributors<br>Os estabelecimentos da lista são exemplos fictícios e não estão assinalados no mapa.</div></div>`}
function appt(b){const d=new Date(b.date+'T12:00:00');return `<div class="appointment"><div class="date-tile"><span>${d.toLocaleDateString('pt-PT',{month:'short'}).replace('.','')}</span><b>${d.getDate()}</b></div><div><h3>${esc(b.specialty)}</h3><p>${esc(b.doctor)}</p><p>${esc(b.time)} · ${esc(b.type)}</p></div>${b.type==='Teleconsulta'?pageButton('Entrar','video','soft'):button('Detalhes','booking-detail','secondary',`data-id="${b.id}"`)}</div>`}
function home(){return intro('O seu espaço de saúde','Olá, visitante.','Tudo o que precisa para cuidar de si, num só lugar.')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">FEITO PARA ANGOLA</div><h1>A sua saúde,<br>mais perto de si.</h1><p>Encontre cuidados em Luanda e organize a sua próxima consulta, onde estiver.</p>${pageButton(`Encontrar cuidados ${icon('arrow')}`,'discover','light')}</div><div class="hero-art" aria-hidden="true"><div class="care-ring"><div class="care-cross">${icon('cross')}</div><span class="ring-label one">${icon('shield')} Consigo, em cada passo</span><span class="ring-label two">Luanda · Angola</span></div></div></section><div class="section-title"><h2>Como podemos ajudar?</h2><span class="small muted">Cuidados à sua medida</span></div><div class="services">${[['appointments','calendar','Marcar consulta','Escolha o dia e a especialidade',''],['discover','pill','Encontrar farmácia','Explore a sua zona','blue'],['video','video','Teleconsulta','Cuidados à distância','purple'],['ambulance','ambulance','Pedir ambulância','Simular um pedido','red']].map(([p,i,t,s,c])=>`<button class="service" data-page="${p}" ${p==='discover'?'data-category-target="Farmácias"':'' }><span class="icon-box ${c}">${icon(i)}</span><span class="chevron">${icon('chevron')}</span><h3>${t}</h3><p>${s}</p></button>`).join('')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Próximas consultas</h2>${pageButton('Ver todas','appointments','ghost')}</div>${state.bookings.length?state.bookings.slice(0,2).map(appt).join(''):'<p class="muted">Ainda não tem consultas de demonstração.</p>'}<span class="small muted">Agenda de exemplo · sem marcações reais</span></section><section class="panel"><div class="panel-head"><h2>A sua saúde organizada</h2><span class="pill">O seu espaço</span></div><div class="health-row"><span class="icon-box">${icon('file')}</span><div><strong>Documentos de saúde</strong><p>Resultados e certificados, num só lugar.</p></div>${pageButton(icon('chevron'),'documents','ghost')}</div><div class="health-row"><span class="icon-box blue">${icon('user')}</span><div><strong>Perfil e privacidade</strong><p>Conheça os controlos da sua conta.</p></div>${pageButton(icon('chevron'),'profile','ghost')}</div></section></div>`+note()}
function providerCards(){const q=state.query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const rows=providers.filter(p=>(state.category==='Todos'||p.type===state.category)&&(state.area==='Luanda'||p.zone===state.area)&&(`${p.name} ${p.zone} ${p.type}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)));return rows.length?rows.map(p=>`<article class="provider"><div class="icon-box ${p.type==='Clínicas'?'blue':''}">${icon(p.icon)}</div><div class="provider-main"><h3>${p.name}</h3><p>${p.type} · ${p.zone}, Luanda</p><p>Horário ilustrativo: ${p.hours}</p><div class="provider-actions"><span class="pill orange">Exemplo fictício</span>${button(`Ver detalhes ${icon('arrow')}`,'provider','ghost',`data-name="${p.name}"`)}</div></div></article>`).join(''):'<div class="panel empty">Nenhum exemplo corresponde à pesquisa. Experimente outra zona ou categoria.</div>'}
function discover(){return intro('ENCONTRAR CUIDADOS','Perto de si, em Luanda.','Explore farmácias, clínicas e laboratórios por zona.')+`<div class="search-bar"><div class="input-wrap">${icon('search')}<label class="screen-reader" for="search">Pesquisar estabelecimento ou zona</label><input id="search" placeholder="Pesquisar farmácia, clínica ou zona…" value="${esc(state.query)}"></div><label class="screen-reader" for="area">Zona</label><select id="area" style="max-width:180px">${Object.keys(areas).map(a=>`<option ${a===state.area?'selected':''}>${a}</option>`).join('')}</select>${button(`${icon('pin')} Usar GPS`,'gps','secondary')}</div><div class="filters">${['Todos','Farmácias','Clínicas','Laboratórios'].map(c=>`<button class="chip ${c===state.category?'selected':''}" data-category="${c}" aria-pressed="${c===state.category}">${c}</button>`).join('')}</div><div class="directory"><div><p class="small muted">DIRECTÓRIO DE DEMONSTRAÇÃO</p><div id="provider-list">${providerCards()}</div>${button('Consultar directório real do Azure','live-directory','secondary full')}<div id="live-result" class="small muted" role="status"></div></div><div>${map(state.area)}<p class="small muted">O mapa pode ser explorado. Os horários e nomes de exemplo não representam parceiros confirmados.</p></div></div>`}
function appointments(){return intro('A SUA AGENDA','Tempo para cuidar de si.','Simule uma marcação em poucos passos.')+`<div class="booking-layout"><section class="panel"><div class="step">NOVA CONSULTA · DEMONSTRAÇÃO</div><h2 style="margin-top:12px">Escolha os seus cuidados</h2><form id="booking-form"><div class="form-grid"><div><label for="specialty">Especialidade</label><select id="specialty"><option>Medicina geral</option><option>Pediatria</option><option>Cardiologia</option><option>Dermatologia</option></select></div><div><label for="consult-type">Tipo de consulta</label><select id="consult-type"><option>Teleconsulta</option><option>Presencial</option></select></div></div><label for="book-date">Data</label><input id="book-date" type="date" min="${dayIso(new Date())}" value="${dayIso(tomorrow)}" required><label>Horários de exemplo</label><div class="time-grid">${['09:00','10:30','14:00','16:30'].map(t=>`<button type="button" class="slot ${t===state.slot?'selected':''}" data-slot="${t}" aria-pressed="${t===state.slot}">${t}</button>`).join('')}</div><div class="notice">Não é necessário inserir dados pessoais. Os horários são fictícios e não verificam disponibilidade médica.</div><button class="btn full" type="submit">Simular marcação ${icon('arrow')}</button></form></section><div><section class="panel"><h2>A sua agenda de exemplo</h2>${state.bookings.length?state.bookings.map(b=>`<div>${appt(b)}${button('Cancelar exemplo','cancel-booking','ghost',`data-id="${b.id}"`)}</div>`).join(''):'<p class="muted">Sem consultas. Experimente uma nova marcação.</p>'}</section><div class="notice">Pagamentos serão acrescentados numa fase posterior. Esta demonstração não cobra qualquer valor.</div></div></div>`}
function video(){return intro('TELECONSULTA','Cuidados, onde estiver.','Explore a experiência de uma consulta à distância.')+`<div class="booking-layout"><div><div class="video-stage"><span class="video-badge">${state.videoActive?'SESSÃO DE DEMONSTRAÇÃO':'SALA DE ESPERA · DEMO'}</span><div><div class="initials">${icon('video')}</div><h2>${state.videoActive?'A sua teleconsulta, num só espaço.':'Tudo pronto para entrar?'}</h2><p>${state.videoActive?'Nenhum médico está ligado. Câmara e microfone não são utilizados.':'Experimente a sala virtual sem activar a câmara ou o microfone.'}</p>${state.videoActive?'<span class="pill">Simulação em curso</span>':button('Entrar na sala de demonstração','start-video','light')}</div></div><div class="video-controls"><button data-action="mic" class="${state.mic?'':'off'}" aria-label="${state.mic?'Simular desligar':'Simular ligar'} microfone" aria-pressed="${state.mic}">${icon('mic')}</button><button data-action="camera" class="${state.camera?'':'off'}" aria-label="${state.camera?'Simular desligar':'Simular ligar'} câmara" aria-pressed="${state.camera}">${icon('video')}</button><button data-action="end-video" class="end" aria-label="Terminar demonstração">${icon('phone')}</button></div>${note('Controlos ilustrativos. Não captamos áudio, vídeo ou dados clínicos.')}</div><section class="panel"><div class="eyebrow">ANTES DE COMEÇAR</div><h2 style="margin-top:12px">O seu espaço de consulta</h2><ul class="checklist"><li>${icon('check')} Escolha um local tranquilo.</li><li>${icon('check')} Tenha uma ligação estável à Internet.</li><li>${icon('check')} Tenha os seus documentos à mão.</li></ul><div class="health-row"><span class="icon-box">${icon('file')}</span><div><strong>Documentos</strong><p>Veja o exemplo de organização.</p></div></div>${pageButton('Ver documentos','documents','secondary full')}<div class="notice">A ligação a médicos e ao serviço de vídeo real ainda está em preparação.</div></section></div>`}
function documents(){return intro('OS SEUS DOCUMENTOS','Tudo no seu lugar.','Explore a organização e o reconhecimento de documentos.')+`<div class="booking-layout"><section class="panel"><div class="panel-head"><h2>Biblioteca de exemplo</h2><span class="pill">${state.docs?3:2} documentos</span></div>${[['Resumo de consulta','Documento fictício · PDF','summary'],['Certificado profissional','Documento fictício · verificação pendente','certificate'],...(state.docs?[['Documento de exemplo processado','Extracção simulada · revisão necessária','ocr']]:[])].map(([t,d,k])=>`<div class="document-card"><span class="icon-box ${k==='certificate'?'blue':''}">${icon('file')}</span><div><h3>${t}</h3><p>${d}</p></div>${button('Abrir','document','secondary',`data-kind="${k}"`)}</div>`).join('')}<div class="upload-demo"><div class="eyebrow">RECONHECIMENTO DE DOCUMENTOS</div><h3 style="margin-top:12px">Do documento aos campos organizados.</h3><p class="small muted">Experimente com um ficheiro de exemplo. Não envie documentos pessoais nesta versão.</p>${button(`${icon('file')} Processar exemplo`,'ocr')}</div></section><section class="panel"><h2>Como vai funcionar</h2>${[['Adicionar documento','Envio privado, associado à sua conta.'],['Reconhecer os campos','Nome, tipo, emissor e datas extraídos para revisão.'],['Rever e confirmar','A pessoa responsável verifica os dados antes de guardar.']].map(([t,d],i)=>`<div class="journey"><span class="number">${i+1}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}<div class="notice">A leitura automática de um certificado não comprova a sua autenticidade. A verificação profissional é uma etapa separada.</div></section></div>`}
function ambulance(){return intro('TRANSPORTE E ASSISTÊNCIA','Localização clara. Pedido simples.','Veja como será o pedido de ambulância na KAYA.')+`<div class="notice warn"><strong>Apenas demonstração — não envia uma ambulância.</strong><br>Não utilize este protótipo para pedir assistência numa emergência real.</div><div class="booking-layout"><section class="panel"><div class="step">SIMULAR UM PEDIDO</div><form id="ambulance-form"><label for="pickup-zone">Zona de recolha</label><select id="pickup-zone"><option>Maianga</option><option>Talatona</option><option>Luanda</option></select><label for="pickup">Ponto de encontro de exemplo</label><select id="pickup"><option>Entrada principal do edifício de demonstração</option><option>Recepção da clínica de demonstração</option></select><label for="transport">Tipo de transporte</label><select id="transport"><option>Transporte para consulta</option><option>Transferência entre unidades</option></select><div class="notice">Nesta fase, use apenas pontos de encontro fictícios. A operação real depende de parceiros e confirmação de disponibilidade.</div><button class="btn danger full" type="submit">Simular pedido ${icon('arrow')}</button></form></section><div id="ambulance-map">${map('Maianga')}</div></div>`}
function profile(){return intro('A SUA CONTA','Privacidade desde o início.','Um perfil de apresentação, sem dados pessoais reais.')+`<div class="two-col"><section class="panel"><div class="health-row"><span class="avatar">V</span><div><h2>Visitante KAYA</h2><p>Perfil de demonstração · Angola</p></div></div><div class="summary-row"><span>Idioma</span><strong>Português</strong></div><div class="summary-row"><span>País</span><strong>Angola</strong></div><div class="summary-row"><span>Modo de acesso</span><strong>Demonstração</strong></div><div class="summary-row"><span>Dados guardados</span><strong>Apenas nesta sessão</strong></div>${button(`${icon('refresh')} Reiniciar demonstração`,'reset','secondary full','style="margin-top:24px"')}</section><section class="panel"><h2>Construído para a sua confiança</h2><ul class="checklist"><li>${icon('shield')} Conta individual com controlo de acesso.</li><li>${icon('file')} Documentos privados por utilizador.</li><li>${icon('user')} Permissões distintas para clientes e profissionais.</li></ul><div class="notice">Estes controlos fazem parte da implementação planeada. O protótipo não autentica utilizadores nem permite enviar dados de saúde.</div>${button('Ver estado das integrações','integrations','secondary full')}</section></div>`}
function render(){const page=current();const views={home,discover,appointments,video,documents,ambulance,profile};document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home" aria-label="KAYA Saúde, início"><span class="brand-mark">+</span><span>KAYA<em>SAÚDE</em></span></a><div class="nav-label">O SEU CUIDADO</div><nav aria-label="Menu principal">${nav.map(([p,n,i])=>`<button data-page="${p}" class="${p===page?'active':''}" ${p===page?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('')}<button class="mobile-more ${['video','ambulance','profile'].includes(page)?'active':''}" data-action="menu" aria-haspopup="dialog">${icon('info')}<span>Mais</span></button></nav><div class="sidebar-bottom"><div class="pilot-box">${icon('shield')}<strong>Começamos em Angola.</strong><span class="muted">Cuidados mais próximos, passo a passo.</span></div><button data-action="integrations">Sobre esta demonstração ${icon('arrow')}</button></div></aside><div class="main"><header class="topbar"><span class="mobile-brand">KAYA</span><div class="location">${icon('pin')}<span><strong>Luanda</strong> <span class="muted">· Angola</span></span></div><div class="top-right"><span class="demo-tag">PROTÓTIPO · DEMO</span><button class="btn ghost" data-action="notifications" aria-label="Notificações">${icon('bell')}</button><button class="avatar" data-page="profile" aria-label="Abrir perfil">V</button></div></header><main id="content" tabindex="-1" class="content">${views[page]()}<footer class="foot"><span>KAYA Saúde · Angola primeiro.</span><span>Protótipo de apresentação · serviços simulados</span></footer></main></div></div>`;bind();document.title=`KAYA · ${nav.find(n=>n[0]===page)[1]}`}
function modal(html){const dialog=document.getElementById('modal');document.getElementById('modal-content').innerHTML=html;const title=dialog.querySelector('h2');if(title){title.id='dialog-title';dialog.setAttribute('aria-labelledby','dialog-title')}if(!dialog.open)dialog.showModal()}
function providerDetail(name){const p=providers.find(x=>x.name===name);if(!p)return;modal(`<span class="pill orange">Estabelecimento fictício</span><h2 style="margin-top:18px">${p.name}</h2><p>${p.type} · ${p.zone}, Luanda</p><div class="summary-row"><span>Horário ilustrativo</span><strong>${p.hours}</strong></div><div class="summary-row"><span>Parceria confirmada</span><strong>Não</strong></div><p class="notice">Este cartão demonstra a experiência de descoberta. Não disponibiliza contactos, stock ou direcções para um estabelecimento real.</p>${button('Explorar esta zona no mapa','zone','full',`data-zone="${p.zone}"`)}`)}
const actions={
'menu':()=>modal(`<h2>Todos os serviços</h2><div class="service-menu">${nav.map(([p,n,i])=>pageButton(icon(i)+' '+n,p,'secondary full')).join('')}${button('Sobre esta demonstração','integrations','secondary full')}</div>`),
'provider':el=>providerDetail(el.dataset.name),
'zone':el=>{state.area=el.dataset.zone;document.getElementById('modal').close();go('discover')},
'notifications':()=>modal(`<h2>As suas notificações</h2><div class="health-row"><span class="icon-box">${icon('calendar')}</span><div><strong>Lembrete de consulta</strong><p>Exemplo: receberá uma confirmação e um lembrete antes da consulta.</p></div></div><p class="notice">Nenhuma mensagem, SMS ou notificação real é enviada nesta demonstração.</p>`),
'booking-detail':el=>{const b=state.bookings.find(b=>b.id===Number(el.dataset.id));if(b)modal(`<h2>Consulta de demonstração</h2><p>${esc(b.specialty)} · ${esc(b.type)}</p><p>${dateLabel(b.date)} às ${esc(b.time)}</p><div class="notice">Esta marcação existe apenas na sessão de apresentação. Não há reserva real.</div>`)},
'cancel-booking':el=>{const id=Number(el.dataset.id);state.bookings=state.bookings.filter(b=>b.id!==id);render();toast('Consulta de exemplo cancelada.')},
'start-video':()=>{state.videoActive=true;render()},
'end-video':()=>{state.videoActive=false;render();toast('Demonstração terminada. Não houve qualquer ligação real.')},
'mic':()=>{state.mic=!state.mic;render();document.querySelector('[data-action="mic"]').focus({preventScroll:true});toast(`Microfone ${state.mic?'ligado':'desligado'} na simulação. Nenhum áudio captado.`)},
'camera':()=>{state.camera=!state.camera;render();document.querySelector('[data-action="camera"]').focus({preventScroll:true});toast(`Câmara ${state.camera?'ligada':'desligada'} na simulação. Nenhum vídeo captado.`)},
'document':el=>modal(`<div class="eyebrow">DOCUMENTO FICTÍCIO</div><h2 style="margin-top:12px">${el.dataset.kind==='certificate'?'Certificado profissional — exemplo':'Resumo de documento — exemplo'}</h2><div class="summary-row"><span>Titular</span><strong>Pessoa de demonstração</strong></div><div class="summary-row"><span>Emissor</span><strong>Entidade de exemplo</strong></div><div class="summary-row"><span>Estado</span><strong>Revisão pendente</strong></div><div class="notice">Conteúdo ilustrativo, sem validade clínica ou profissional. Não representa um certificado verificado.</div>`),
'ocr':()=>{state.docs=true;render();modal(`<div class="success"><div class="success-icon">${icon('file')}</div><h2>Campos organizados.</h2><p>A simulação extraiu os campos do documento de exemplo.</p></div><div class="summary-row"><span>Tipo</span><strong>Certificado profissional</strong></div><div class="summary-row"><span>Nome</span><strong>Pessoa de demonstração</strong></div><div class="summary-row"><span>Emissor</span><strong>Entidade de exemplo</strong></div><div class="notice">Extracção simulada. Nenhum ficheiro foi enviado ao Azure. Os campos e a autenticidade exigem revisão.</div>`)},
'reset':()=>{modal(`<h2>Reiniciar a apresentação?</h2><p>As marcações e documentos de exemplo desta sessão serão repostos.</p>${button('Reiniciar exemplos','confirm-reset','full')}`)},
'confirm-reset':()=>{Object.assign(state,{category:'Todos',query:'',area:'Luanda',bookings:[{...initialBooking}],slot:'10:30',docs:false,videoActive:false,mic:true,camera:true,ambulance:false});document.getElementById('modal').close();go('home');toast('Demonstração pronta para apresentar.')},
'integrations':()=>modal(`<div class="eyebrow">TRANSPARÊNCIA</div><h2 style="margin-top:12px">O que está ligado?</h2><div class="summary-row"><span>Mapa</span><strong>OpenStreetMap real</strong></div><div class="summary-row"><span>Directório Azure</span><strong>Consulta pública disponível</strong></div><div class="summary-row"><span>Login do protótipo</span><strong>Modo visitante</strong></div><div class="summary-row"><span>Consultas, vídeo e OCR</span><strong>Simulados</strong></div><div class="summary-row"><span>Ambulâncias</span><strong>Sem envio real</strong></div><div class="summary-row"><span>Pagamentos</span><strong>Fase posterior</strong></div><p class="small muted" style="margin-top:18px">O código deste protótipo é independente do projecto FlutterFlow. O backend KAYA continua no Azure.</p>`),
'gps':()=>modal(`<h2>Localização neste protótipo</h2><p>Para a apresentação, pode usar Luanda como localização de exemplo ou testar o GPS do seu dispositivo.</p><p class="small muted">O GPS mostra as coordenadas apenas neste ecrã. Não as guardamos nem enviamos ao Azure ou ao mapa. O navegador pedirá autorização.</p><div class="toolbar">${button('Usar Luanda de exemplo','sample-location')}${button('Testar o GPS do dispositivo','real-gps','secondary')}</div><div id="gps-result" role="status"></div>`),
'sample-location':()=>{state.area='Luanda';document.getElementById('modal').close();go('discover');toast('Luanda seleccionada como localização de exemplo.')},
'real-gps':()=>{const out=document.getElementById('gps-result');if(!navigator.geolocation){out.textContent='GPS indisponível neste navegador. Pode escolher uma zona manualmente.';return}out.textContent='A aguardar autorização do navegador…';navigator.geolocation.getCurrentPosition(p=>{out.textContent=`Localização recebida: ${p.coords.latitude.toFixed(4)}, ${p.coords.longitude.toFixed(4)}. Coordenadas apenas nesta janela; o mapa continua centrado na zona seleccionada.`},()=>{out.textContent='Não foi possível obter a localização. Pode continuar com a selecção manual da zona.'},{timeout:10000,maximumAge:60000})},
'live-directory':async el=>{el.disabled=true;const out=document.getElementById('live-result');out.textContent='A consultar o directório público KAYA… Pode demorar até 30 segundos.';const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch(apiBase+'/api/v1/care-locations?category=pharmacy',{signal:controller.signal,credentials:'omit'});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data.items))throw Error();out.textContent=data.items.length?`${data.items.length} estabelecimento(s) devolvido(s) pelo directório Azure. A lista acima continua a ser uma demonstração.`:'Ligação ao Azure confirmada. Ainda não há farmácias verificadas no directório real; os cartões acima são apenas exemplos.'}catch{out.textContent='O directório real não está acessível neste momento. Pode continuar a apresentação com os exemplos.'}finally{clearTimeout(timer);el.disabled=false}}
};
function bind(){const search=document.getElementById('search');if(search)search.addEventListener('input',e=>{state.query=e.target.value;document.getElementById('provider-list').innerHTML=providerCards()});document.getElementById('area')?.addEventListener('change',e=>{state.area=e.target.value;render()});document.getElementById('pickup-zone')?.addEventListener('change',e=>{document.getElementById('ambulance-map').innerHTML=map(e.target.value)});document.getElementById('booking-form')?.addEventListener('submit',e=>{e.preventDefault();const specialty=document.getElementById('specialty').value,type=document.getElementById('consult-type').value,date=document.getElementById('book-date').value;if(!date||date<dayIso(new Date())){toast('Escolha hoje ou uma data futura.');return}const booking={id:Date.now(),specialty,type,date,time:state.slot,doctor:'Profissional · perfil de exemplo'};state.bookings.push(booking);render();modal(`<div class="success"><div class="success-icon">${icon('check')}</div><div class="eyebrow">SIMULAÇÃO CONCLUÍDA</div><h2 style="margin-top:10px">A sua consulta está na agenda de exemplo.</h2><p>${esc(specialty)} · ${esc(type)}<br>${dateLabel(date)} às ${state.slot}</p><div class="notice">Nenhuma reserva real foi feita. Não haverá cobrança ou contacto de um profissional.</div>${pageButton('Voltar ao início','home','full')}</div>`)});document.getElementById('ambulance-form')?.addEventListener('submit',e=>{e.preventDefault();state.ambulance=true;const zone=document.getElementById('pickup-zone').value;const pickup=document.getElementById('pickup').value;const transport=document.getElementById('transport').value;modal(`<div class="success"><div class="success-icon">${icon('ambulance')}</div><div class="eyebrow">SIMULAÇÃO CONCLUÍDA</div><h2 style="margin-top:12px">Assim será o resumo do pedido.</h2><p>Zona: ${esc(zone)}<br>${esc(pickup)}<br>${esc(transport)}<br>Referência de demonstração: KAYA-DEMO-001</p></div><div class="notice warn"><strong>Nenhuma ambulância foi enviada.</strong> Numa versão operacional, o parceiro terá de confirmar a disponibilidade antes de existir uma estimativa de chegada.</div>${pageButton('Voltar ao início','home','full')}`)})}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.page){document.getElementById('modal').close();if(el.dataset.page==='discover'&&current()==='home'){state.category=el.dataset.categoryTarget||'Todos';state.query='';state.area='Luanda'}go(el.dataset.page)}else if(el.dataset.category){state.category=el.dataset.category;render()}else if(el.dataset.slot){state.slot=el.dataset.slot;document.querySelectorAll('[data-slot]').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',String(b===el))})}else if(el.dataset.action&&actions[el.dataset.action])actions[el.dataset.action](el)});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('content').focus()});
document.querySelector('#modal .close').addEventListener('click',()=>document.getElementById('modal').close());document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);document.getElementById('content').focus({preventScroll:true})});render();
